/// <summary>
/// Helper class for the load planning report - SO & TO.
/// </summary>
public class METLoadPlanningReportHelper
{
}

Method.Source:
/// <summary>
/// Insert the data into load planning aid table and return the transaction id for further processingl.
/// </summary>
/// <param name = "_industryKey">Industry key</param>
/// <param name = "_inventLocation">Warehouse</param>
/// <param name = "_metInventLocation">MET warehouse details</param>
/// <param name = "_salesTable">Sales order</param>
/// <param name = "_metSalesTable">MET sales order details</param>
/// <param name = "_orderExtractScreenTmp">SO extraction screen records</param>
/// <param name = "_userConnection">User connection</param>
/// <returns>Created transactionid</returns>
public static CreatedTransactionId getSOLoadPlanningAidTxnId(METIndustryKeyTable _industryKey, InventLocation _inventLocation, 
    METInventLocation           _metInventLocation, 
    SalesTable                  _salesTable,
    METSalesTable               _metSalesTable, 
    METOrderExtractScreenTmp    _orderExtractScreenTmp, 
    UserConnection              _userConnection,
    Map                         _metricsCacheMap)
{
    RecordInsertList    salesOrdLoadPlanningLinesList   = new RecordInsertList(tableNum(METsalesOrderLoadPlanningAidLines));
    METsalesOrderLoadPlanningAidLines salesOrderLoadPlanningAidLinesTmp;

    salesOrderLoadPlanningAidLinesTmp.setConnection(_userConnection);

    salesOrderLoadPlanningAidLinesTmp.clear();

    salesOrderLoadPlanningAidLinesTmp.CompanyName               = _industryKey.CompanyName;
    salesOrderLoadPlanningAidLinesTmp.WareHouse                 = _inventLocation.Name;
    salesOrderLoadPlanningAidLinesTmp.ReportGeneratedDateTime   = DateTimeUtil::getSystemDateTime();
    salesOrderLoadPlanningAidLinesTmp.Route                     = _salesTable.METRoute;
    salesOrderLoadPlanningAidLinesTmp.ConfirmedShipDate         = _salesTable.ShippingDateConfirmed;
    salesOrderLoadPlanningAidLinesTmp.StopNumber                = _salesTable.METRouteStopNum;
    salesOrderLoadPlanningAidLinesTmp.SalesId                   = _salesTable.SalesId;
    salesOrderLoadPlanningAidLinesTmp.LineNum                   = _orderExtractScreenTmp.LineNum;
    salesOrderLoadPlanningAidLinesTmp.Cases                     = _metricsCacheMap.exists(_orderExtractScreenTmp.RecId) ? conPeek(_metricsCacheMap.lookup(_orderExtractScreenTmp.RecId), 1) : 0;
    salesOrderLoadPlanningAidLinesTmp.Eaches                    = _metricsCacheMap.exists(_orderExtractScreenTmp.RecId) ? conPeek(_metricsCacheMap.lookup(_orderExtractScreenTmp.RecId), 2) : 0;
    salesOrderLoadPlanningAidLinesTmp.Weight                    = _metricsCacheMap.exists(_orderExtractScreenTmp.RecId) ? conPeek(_metricsCacheMap.lookup(_orderExtractScreenTmp.RecId), 8) : 0;
    salesOrderLoadPlanningAidLinesTmp.Volume                    = _metricsCacheMap.exists(_orderExtractScreenTmp.RecId) ? conPeek(_metricsCacheMap.lookup(_orderExtractScreenTmp.RecId), 7) : 0;
    salesOrderLoadPlanningAidLinesTmp.OrderCreatedDateTime      = _salesTable.CreatedDateTime;
    salesOrderLoadPlanningAidLinesTmp.OrderType                 = _salesTable.METSalesOrderType;
    salesOrderLoadPlanningAidLinesTmp.OrderSplitGroup           = _metSalesTable.OrderSplitGroup;
    salesOrderLoadPlanningAidLinesTmp.CustAccount               = _salesTable.CustAccount;
    salesOrderLoadPlanningAidLinesTmp.CustomerName              = _salesTable.SalesName;
    salesOrderLoadPlanningAidLinesTmp.OrderSplitCategoryCode    = _metSalesTable.OrderSplitGroup;

    if (_metInventLocation.WHSPalletVolume != 0)
    {
        salesOrderLoadPlanningAidLinesTmp.Pallets = (salesOrderLoadPlanningAidLinesTmp.Volume/_metInventLocation.WHSPalletVolume);
    }
    else
    {
        salesOrderLoadPlanningAidLinesTmp.Pallets = salesOrderLoadPlanningAidLinesTmp.Volume;
    }

    salesOrderLoadPlanningAidLinesTmp.Pallets = roundUpDec(salesOrderLoadPlanningAidLinesTmp.Pallets, 1);

    salesOrderLoadPlanningAidLinesTmp.insert();

    return salesOrderLoadPlanningAidLinesTmp.CreatedTransactionId;
}

/// <summary>
/// Setting table for LoadPlanningreport
/// </summary>
/// <param name = "selectedRecords">selectedRecords</param>
/// <param name = "_orderExtractScreenTmp">METTransferOrderExtractScreenTmp buffer</param>
/// <returns>CreatedTransactionID</returns>
public static CreatedTransactionID setSOReportLoadPlanningAidTmp(Map _selectedRecords, METOrderExtractScreenTmp _orderExtractScreenTmp, Map _metricsCacheMap)
{
    SalesId                                 salesId;
    SalesTable                              salesTable;
    METSalesTable                           metSalesTable;
    UserConnection                          userConnection = new UserConnection(true);
    InventLocation                          inventLocation;
    METInventLocation                       metInventLocation;
    METIndustryKeyTable                     industryKeyTable;
    CreatedTransactionId                    transactionId;
    METOrderExtractScreenTmp                orderExtractScreenTmp;

    orderExtractScreenTmp.linkPhysicalTableInstance(_orderExtractScreenTmp);

    userConnection.ttsbegin();

    if (!_selectedRecords.empty())
    {
        MapIterator mapIterator = new MapIterator(_selectedRecords);

        while (mapIterator.more())
        {
            salesId = mapIterator.value();

            select orderExtractScreenTmp
                where orderExtractScreenTmp.SalesId == salesId
                join CustAccount, METRoute, ShippingDateConfirmed, METRouteStopNum, SalesId, CreatedDateTime, METSalesOrderType, SalesName from salesTable
                where salesTable.SalesId == orderExtractScreenTmp.SalesId
                join OrderSplitGroup from metSalesTable
                where metSalesTable.SalesTable == salesTable.RecId
                join Name, METWHSubEntity, RecId from inventLocation
                where inventLocation.InventLocationId == salesTable.InventLocationId
                join WHSPalletVolume from metInventLocation
                where metInventLocation.InventLocation == inventLocation.RecId
                join CompanyName from industryKeyTable
                where industryKeyTable.IndustryKey == inventLocation.METWHSubEntity;

            transactionId = METLoadPlanningReportHelper::getSOLoadPlanningAidTxnId(
                industryKeyTable, 
                inventLocation, 
                metInventLocation, 
                salesTable, 
                metSalesTable, 
                orderExtractScreenTmp, 
                userConnection,
                _metricsCacheMap);

            mapIterator.next();
        }
    }
    else
    {
        while select orderExtractScreenTmp
            join CustAccount, METRoute, ShippingDateConfirmed, METRouteStopNum, SalesId, CreatedDateTime, METSalesOrderType, SalesName from salesTable
            where salesTable.SalesId == orderExtractScreenTmp.SalesId
            join OrderSplitGroup from metSalesTable
            where metSalesTable.SalesTable == salesTable.RecId
            join Name, METWHSubEntity, RecId from inventLocation
            where inventLocation.InventLocationId == salesTable.InventLocationId
            join WHSPalletVolume from metInventLocation
            where metInventLocation.InventLocation == inventLocation.RecId
            join CompanyName from industryKeyTable
            where industryKeyTable.IndustryKey == inventLocation.METWHSubEntity
        {
            transactionId = METLoadPlanningReportHelper::getSOLoadPlanningAidTxnId(
                industryKeyTable,
                inventLocation,
                metInventLocation,
                salesTable,
                metSalesTable,
                orderExtractScreenTmp,
                userConnection,
                _metricsCacheMap);
        }
    }
    userConnection.ttscommit();

    return transactionId;
}

/// <summary>
/// Insert the data into load planning table and return the transaction id for further processing.
/// </summary>
/// <param name = "_industryKey">Industry key</param>
/// <param name = "_inventLocation">Warehouse</param>
/// <param name = "_metInventLocation">MET warehouse details</param>
/// <param name = "_salesTable">Sales order</param>
/// <param name = "_metSalesTable">MET sales order details</param>
/// <param name = "_orderExtractScreenTmp">SO extraction screen records</param>
/// <param name = "_userConnection">User connection</param>
/// <returns>Created transactionid</returns>
public static CreatedTransactionId getSOLoadPlanningTxnId(
    LogisticsAddressCountyId    _suburb,
    InventLocation              _inventLocation,
    SalesTable                  _salesTable,
    METSalesTable               _metSalesTable,
    METOrderExtractScreenTmp    _orderExtractScreenTmp,
    UserConnection              _userConnection,
    Map                         _metricsCacheMap)
{
    METsalesOrderLoadPlanningLines salesOrderLoadPlanningLinesTmp;

    SalesLine                         salesLine;

    salesOrderLoadPlanningLinesTmp.setConnection(_userConnection);

    salesOrderLoadPlanningLinesTmp.clear();

    salesOrderLoadPlanningLinesTmp.WareHouseName        = _inventLocation.Name;
    salesOrderLoadPlanningLinesTmp.Customer             = _salesTable.CustAccount;
    salesOrderLoadPlanningLinesTmp.CustomerName         = _salesTable.SalesName;
    salesOrderLoadPlanningLinesTmp.Suburb               = _suburb;
    salesOrderLoadPlanningLinesTmp.ConfirmedShipDate    = _salesTable.ShippingDateConfirmed;
    salesOrderLoadPlanningLinesTmp.Route                = _salesTable.METRoute;
    salesOrderLoadPlanningLinesTmp.RouteStop            = _salesTable.METRouteStopNum;
    salesOrderLoadPlanningLinesTmp.StagingLane          = _metSalesTable.StagingLaneId;
    salesOrderLoadPlanningLinesTmp.SalesId              = _salesTable.SalesId;
    salesOrderLoadPlanningLinesTmp.LineNum              = _orderExtractScreenTmp.LineNum;
    salesOrderLoadPlanningLinesTmp.BrokenCase           = _metricsCacheMap.exists(_orderExtractScreenTmp.RecId) ? conPeek(_metricsCacheMap.lookup(_orderExtractScreenTmp.RecId), 6) : 0;
    salesOrderLoadPlanningLinesTmp.Cases                = _metricsCacheMap.exists(_orderExtractScreenTmp.RecId) ? conPeek(_metricsCacheMap.lookup(_orderExtractScreenTmp.RecId), 1) : 0;
    salesOrderLoadPlanningLinesTmp.TotalVolume          = _metricsCacheMap.exists(_orderExtractScreenTmp.RecId) ? conPeek(_metricsCacheMap.lookup(_orderExtractScreenTmp.RecId), 7) : 0;
    salesOrderLoadPlanningLinesTmp.TotalWeight          = _metricsCacheMap.exists(_orderExtractScreenTmp.RecId) ? conPeek(_metricsCacheMap.lookup(_orderExtractScreenTmp.RecId), 8) : 0;

    select firstonly salesline
        where salesLine.SalesId == _salesTable.SalesId;

    METOSCCode oscc = salesLine.displayMETOSCCode();

    if (oscc == METConstants::PPerishableOSCC || oscc == METConstants::FFreshOSCC)
    {
        salesOrderLoadPlanningLinesTmp.OrderSplitGroup = METConstants::OSCCodePER;
    }
    else if (oscc == METConstants::LLiquorOSCC || oscc == METConstants::GroceryOscCode || oscc == METConstants::SSlowMovingOSCC || oscc == METConstants::VGeneralMerOSCC)
    {
        salesOrderLoadPlanningLinesTmp.OrderSplitGroup = METConstants::OSCCodeDRY;
    }
    else
    {
        salesOrderLoadPlanningLinesTmp.OrderSplitGroup = '';
    }

    salesOrderLoadPlanningLinesTmp.insert();

    return salesOrderLoadPlanningLinesTmp.CreatedTransactionId;
}

/// <summary>
/// Setting table for LoadPlanningreport
/// </summary>
/// <param name = "selectedRecords">selectedRecords</param>
/// <param name = "_orderExtractScreenTmp">METOrderExtractScreenTmp buffer</param>
/// <returns>CreatedTransactionID</returns>
public static CreatedTransactionID setSOReportLoadPlanningTmp(Map _selectedRecords, METOrderExtractScreenTmp _orderExtractScreenTmp, Map    _metricsCacheMap)
{
    SalesId                                 salesId;
    CustTable                               custTable;
    SalesTable                              salesTable;
    DirPartyTable                           dirPartyTable;
    METSalesTable                           metSalesTable;
    UserConnection                          userConnection = new UserConnection(true);
    InventLocation                          inventLocation;
    METInventLocation                       metInventLocation;
    METIndustryKeyTable                     industryKeyTable;
    CreatedTransactionId                    transactionId;
    LogisticsAddressCountyId                suburb;
    METOrderExtractScreenTmp                orderExtractScreenTmp;
    LogisticsLocationRoleRecId              roleDeliveryRecId;

    Map                                     cacheSuburb = new Map(Types::Int64, Types::String);

    roleDeliveryRecId = LogisticsLocationRole::findByName(METConstants::DeliveryAddress).RecId;

    orderExtractScreenTmp.linkPhysicalTableInstance(_orderExtractScreenTmp);

    userConnection.ttsbegin();

    if (!_selectedRecords.empty())
    {
        MapIterator mapIterator = new MapIterator(_selectedRecords);

        while (mapIterator.more())
        {
            salesId = mapIterator.value();

            select orderExtractScreenTmp
                where orderExtractScreenTmp.SalesId == salesId
                join salesTable
                where salesTable.SalesId == orderExtractScreenTmp.SalesId
                join metSalesTable
                where metSalesTable.SalesTable == salesTable.RecId
                join Name from inventLocation
                where inventLocation.InventLocationId == salesTable.InventLocationId
                join InternalCustomer from metInventLocation
                where metInventLocation.InventLocation == inventLocation.RecId
                join CompanyName from industryKeyTable
                where industryKeyTable.IndustryKey == inventLocation.METWHSubEntity
                join Party from custTable
                where custTable.AccountNum == salesTable.CustAccount
                join PrimaryAddressLocation from dirPartyTable
                where dirPartyTable.RecId == custTable.Party;

            if (cacheSuburb.exists(custTable.Party))
            {
                suburb = cacheSuburb.lookup(custTable.Party);
            }
            else
            {
                suburb = METLoadPlanningReportHelper::getPrimaryCustDeliveryAddress(custTable.Party, dirPartyTable.PrimaryAddressLocation, roleDeliveryRecId);
                cacheSuburb.insert(custTable.Party, suburb);
            }

            transactionId = METLoadPlanningReportHelper::getSOLoadPlanningTxnId(
                suburb, 
                inventLocation, 
                salesTable, 
                metSalesTable, 
                orderExtractScreenTmp, 
                userConnection,
                _metricsCacheMap);

            mapIterator.next();
        }
    }
    else
    {
        while select orderExtractScreenTmp
            join CustAccount, SalesId, SalesName, ShippingDateConfirmed, METRoute, METRouteStopNum from salesTable
            where salesTable.SalesId == orderExtractScreenTmp.SalesId
            join StagingLaneId, OrderSplitGroup from metSalesTable
            where metSalesTable.SalesTable == salesTable.RecId
             &&  metSalesTable.OrderProcessingStatus == METSalesOrderProcessingStatus::OptimisationCompleted
            join Name, RecId from inventLocation
            where inventLocation.InventLocationId == salesTable.InventLocationId
            join CompanyName from industryKeyTable
            where industryKeyTable.IndustryKey == inventLocation.METWHSubEntity
            join Party from custTable
            where custTable.AccountNum == salesTable.CustAccount
            join PrimaryAddressLocation from dirPartyTable
            where dirPartyTable.RecId == custTable.Party
        {
            if (cacheSuburb.exists(custTable.Party))
            {
                suburb = cacheSuburb.lookup(custTable.Party);
            }
            else
            {
                suburb = METLoadPlanningReportHelper::getPrimaryCustDeliveryAddress(custTable.Party, dirPartyTable.PrimaryAddressLocation, roleDeliveryRecId);
                cacheSuburb.insert(custTable.Party, suburb);
            }

            transactionId = METLoadPlanningReportHelper::getSOLoadPlanningTxnId(
                suburb,
                inventLocation,
                salesTable,
                metSalesTable,
                orderExtractScreenTmp,
                userConnection,
                _metricsCacheMap);
        }
    }
    userConnection.ttscommit();

    return transactionId;
}

/// <summary>
/// Get city from customer delivery address
/// </summary>
/// <param name = "_party">Dirparty RecId</param>
/// <param name = "_primaryAddressLocation">PrimaryAddressLocation</param>
/// <returns>City Name</returns>
public static LogisticsAddressCityName getPrimaryCustDeliveryAddress(RefRecId _party,
LogisticsLocationRecId _primaryAddressLocation, LogisticsLocationRoleRecId _roleDeliveryRecId)
{
    LogisticsPostalAddress address = DirParty::postalAddress(_party, LogisticsLocationRoleType::Delivery);

    return address.City;

}

/// <summary>
/// Setting table for LoadPlanningreport
/// </summary>
/// <param name = "selectedRecords">selectedRecords</param>
/// <param name = "_transferOrderTmp">METTransferOrderExtractScreenTmp buffer</param>
/// <returns>CreatedTransactionID</returns>
public static CreatedTransactionID setTOReportLoadPlanningTmp(Map                                  selectedRecords,
                                                              METTransferOrderExtractScreenTmp     _transferOrderTmp)
{
    InventTransferTable                 inventTransferTableLocal;
    METInventTransferTableExt           inventTransferTableExt;
    METTransferOrderExtractScreenTmp    orderExtractScreenTmp;
    InventLocation                      inventLocationFrom;
    InventTransferId                    transferId;

    METTransferOrderLoadPlanningLines transferOrderLoadPlanningLinesTmp;

    orderExtractScreenTmp.linkPhysicalTableInstance(_transferOrderTmp);

    ttsbegin;

    if (!selectedRecords.empty())
    {
        MapIterator     mapIterator = new MapIterator(selectedRecords);

        while (mapIterator.more())
        {
            transferId = mapIterator.value();

            select BrokenCase, Cases, Volume, Weight from orderExtractScreenTmp
                where orderExtractScreenTmp.TransferId == transferId
                join ShipDate, TransferId from inventTransferTableLocal
                    where inventTransferTableLocal.TransferId == orderExtractScreenTmp.TransferId
                join Route, RouteStopNum, StagingLane, OrderSplitGroup, InternalCustomer from inventTransferTableExt
                    where inventTransferTableExt.InventTransferTable == inventTransferTableLocal.RecId
                join Name from inventLocationFrom
                    where inventLocationFrom.InventLocationId == inventTransferTableLocal.InventLocationIdFrom;

            transferOrderLoadPlanningLinesTmp.clear();
            transferOrderLoadPlanningLinesTmp.FromWareHouseName = inventLocationFrom.Name;
            transferOrderLoadPlanningLinesTmp.ConfirmedShipDate = inventTransferTableLocal.ShipDate;
            transferOrderLoadPlanningLinesTmp.Route = inventTransferTableExt.Route;
            transferOrderLoadPlanningLinesTmp.RouteStop = inventTransferTableExt.RouteStopNum;
            transferOrderLoadPlanningLinesTmp.StagingLane = inventTransferTableExt.StagingLane;
            transferOrderLoadPlanningLinesTmp.BrokenCase = orderExtractScreenTmp.BrokenCase;
            transferOrderLoadPlanningLinesTmp.Cases = orderExtractScreenTmp.Cases;
            transferOrderLoadPlanningLinesTmp.TotalVolume = orderExtractScreenTmp.Volume;
            transferOrderLoadPlanningLinesTmp.TotalWeight = orderExtractScreenTmp.Weight;

            if (inventTransferTableExt.InternalCustomer)
            {
                transferOrderLoadPlanningLinesTmp.InternalCustomer = inventTransferTableExt.InternalCustomer;

                RefRecId party = CustTable::find(inventTransferTableExt.InternalCustomer).Party;

                if (party != 0)
                {
                    transferOrderLoadPlanningLinesTmp.ToWareHouseName =  DirPartyTable::getName(CustTable::find(inventTransferTableExt.InternalCustomer).Party);

                    DirPartyPostalAddressView   dirPartyPostalAddressView;
                    DirPartyLocationRole        dirPartyLocationRole;
                    LogisticsLocationRecId      primaryAddressLocation = DirPartyTable::findRec(party).PrimaryAddressLocation;

                    select firstonly RecId, City from dirPartyPostalAddressView
                        where dirPartyPostalAddressView.Party == party
                        && dirPartyPostalAddressView.Location == primaryAddressLocation
                        && dirPartyPostalAddressView.ValidFrom <= DateTimeUtil::getSystemDateTime()
                        && dirPartyPostalAddressView.ValidTo >= DateTimeUtil::getSystemDateTime()
                        exists join dirPartyLocationRole
                            where dirPartyLocationRole.PartyLocation == dirPartyPostalAddressView.RecId
                            && dirPartyLocationRole.LocationRole == LogisticsLocationRole::findByName(METConstants::DeliveryAddress).RecId;

                    transferOrderLoadPlanningLinesTmp.Suburb = dirPartyPostalAddressView.City;
                }
            }

            InventTransferLine      inventTransferLine;
            METInventTransferLine   metInventTransferLine;

            select firstonly OSCCode from metInventTransferLine
                exists join inventTransferLine
                where inventTransferLine.RecId == metInventTransferLine.InventTransferLine &&
                      inventTransferLine.TransferId == inventTransferTableLocal.TransferId;

            METOSCCode oscc = metInventTransferLine.OSCCode;

            if (oscc == METConstants::PPerishableOSCC || oscc == METConstants::FFreshOSCC)
            {
                transferOrderLoadPlanningLinesTmp.OrderSplitCategoryCode = METConstants::OSCCodePER;
            }
            else if (oscc == METConstants::LLiquorOSCC || oscc == METConstants::GroceryOscCode || oscc == METConstants::SSlowMovingOSCC || oscc == METConstants::VGeneralMerOSCC)
            {
                transferOrderLoadPlanningLinesTmp.OrderSplitCategoryCode = METConstants::OSCCodeDRY;
            }
            else
            {
                transferOrderLoadPlanningLinesTmp.OrderSplitCategoryCode = '';
            }

            transferOrderLoadPlanningLinesTmp.insert();

            mapIterator.next();
        }
    }
    else
    {
        while select BrokenCase, Cases, Volume, Weight from orderExtractScreenTmp
            join ShipDate, TransferId from inventTransferTableLocal
                where inventTransferTableLocal.TransferId == orderExtractScreenTmp.TransferId
            join Route, RouteStopNum, StagingLane, OrderSplitGroup, InternalCustomer from inventTransferTableExt
                where inventTransferTableExt.InventTransferTable == inventTransferTableLocal.RecId
            join Name from inventLocationFrom
                where inventLocationFrom.InventLocationId == inventTransferTableLocal.InventLocationIdFrom
        {
            transferOrderLoadPlanningLinesTmp.clear();
            transferOrderLoadPlanningLinesTmp.FromWareHouseName = inventLocationFrom.Name;
            transferOrderLoadPlanningLinesTmp.ConfirmedShipDate = inventTransferTableLocal.ShipDate;
            transferOrderLoadPlanningLinesTmp.Route = inventTransferTableExt.Route;
            transferOrderLoadPlanningLinesTmp.RouteStop = inventTransferTableExt.RouteStopNum;
            transferOrderLoadPlanningLinesTmp.StagingLane = inventTransferTableExt.StagingLane;
            transferOrderLoadPlanningLinesTmp.BrokenCase = orderExtractScreenTmp.BrokenCase;
            transferOrderLoadPlanningLinesTmp.Cases = orderExtractScreenTmp.Cases;
            transferOrderLoadPlanningLinesTmp.TotalVolume = orderExtractScreenTmp.Volume;
            transferOrderLoadPlanningLinesTmp.TotalWeight = orderExtractScreenTmp.Weight;

            if (inventTransferTableExt.InternalCustomer)
            {
                transferOrderLoadPlanningLinesTmp.InternalCustomer = inventTransferTableExt.InternalCustomer;

                RefRecId party = CustTable::find(inventTransferTableExt.InternalCustomer).Party;

                if (party != 0)
                {
                    transferOrderLoadPlanningLinesTmp.ToWareHouseName =  DirPartyTable::getName(CustTable::find(inventTransferTableExt.InternalCustomer).Party);

                    DirPartyPostalAddressView   dirPartyPostalAddressView;
                    DirPartyLocationRole        dirPartyLocationRole;
                    LogisticsLocationRecId      primaryAddressLocation = DirPartyTable::findRec(party).PrimaryAddressLocation;

                    select firstonly RecId, City from dirPartyPostalAddressView
                        where dirPartyPostalAddressView.Party == party
                        && dirPartyPostalAddressView.Location == primaryAddressLocation
                        && dirPartyPostalAddressView.IsPrimary == NoYes::Yes
                        && dirPartyPostalAddressView.ValidFrom <= DateTimeUtil::getSystemDateTime()
                        && dirPartyPostalAddressView.ValidTo >= DateTimeUtil::getSystemDateTime()
                        exists join dirPartyLocationRole
                            where dirPartyLocationRole.PartyLocation == dirPartyPostalAddressView.RecId
                            && dirPartyLocationRole.LocationRole == LogisticsLocationRole::findByName(METConstants::DeliveryAddress).RecId;

                    LogisticsPostalAddress address = DirParty::postalAddress(party, LogisticsLocationRoleType::Delivery);

                    transferOrderLoadPlanningLinesTmp.Suburb = address.City;
                }
            }

            METOrderSplitGroup orderSplitGrp = subStr(strRem(InventTransferTableExt.OrderSplitGroup, " "), 1, 1);

            if (orderSplitGrp == METConstants::OSCCodeP)
            {
                transferOrderLoadPlanningLinesTmp.OrderSplitCategoryCode = METConstants::OSCCodePER;
            }
            else
            {
                transferOrderLoadPlanningLinesTmp.OrderSplitCategoryCode = METConstants::OSCCodeDRY;
            }

            transferOrderLoadPlanningLinesTmp.insert();
        }
    }

    ttscommit;

    return transferOrderLoadPlanningLinesTmp.CreatedTransactionId;
}

/// <summary>
/// Setting table for LoadPlanningreportAId
/// </summary>
/// <param name = "selectedRecords">selectedRecords</param>
/// <param name = "_transferOrderTmp">_transferOrderTmp</param>
/// <returns>CreatedTransactionID</returns>
public static CreatedTransactionID setTOReportLoadPlanningAIDTmp(Map                                  selectedRecords,
                                                                 METTransferOrderExtractScreenTmp     _transferOrderTmp)
{
    InventTransferTable         inventTransferTable;
    METInventTransferTableExt   metInventTransferTableExt;
    InventLocation              inventLocation;
    METInventLocation           metInventLocation;
    METIndustryKeyTable         industryKeyTable;
    InventTransferId            transferId;

    METTransferOrderExtractScreenTmp    orderExtractScreenTmp;

    METTransferOrderLoadPlanningAidLines transferOrderLoadPlanningAidLinesTmp;

    orderExtractScreenTmp.linkPhysicalTableInstance(_transferOrderTmp);

    ttsbegin;

    MapIterator     mapIterator = new MapIterator(selectedRecords);

    if (!selectedRecords.empty())
    {
        while (mapIterator.more())
        {
            transferId = mapIterator.value();

            select TransferId, Cases, BrokenCase, Weight, Volume from orderExtractScreenTmp
                where orderExtractScreenTmp.TransferId == transferId
                join ShipDate, TransferId, CreatedDateTime from inventTransferTable
                    where inventTransferTable.TransferId == orderExtractScreenTmp.TransferId
                join Route, RouteStopNum, OrderSplitGroup, InternalCustomer from metInventTransferTableExt
                    where metInventTransferTableExt.InventTransferTable == inventTransferTable.RecId
                 join Name, METWHSubEntity, RecId from inventLocation
                    where inventLocation.InventLocationId == inventTransferTable.InventLocationIdFrom
                join WHSPalletVolume from metInventLocation
                    where metInventLocation.InventLocation == inventLocation.RecId
                join CompanyName from industryKeyTable
                    where industryKeyTable.IndustryKey == inventLocation.METWHSubEntity;

            transferOrderLoadPlanningAidLinesTmp.CompanyName = industryKeyTable.CompanyName;
            transferOrderLoadPlanningAidLinesTmp.FromWareHouseName = inventLocation.Name;
            transferOrderLoadPlanningAidLinesTmp.ReportGeneratedDateTime = DateTimeUtil::utcNow();
            transferOrderLoadPlanningAidLinesTmp.Route = metInventTransferTableExt.Route;
            transferOrderLoadPlanningAidLinesTmp.DeliveryDate = inventTransferTable.ShipDate;

            transferOrderLoadPlanningAidLinesTmp.TransferId = inventTransferTable.TransferId;
            transferOrderLoadPlanningAidLinesTmp.RouteStop = metInventTransferTableExt.RouteStopNum;
            transferOrderLoadPlanningAidLinesTmp.Cases = orderExtractScreenTmp.Cases;
            transferOrderLoadPlanningAidLinesTmp.Eaches = orderExtractScreenTmp.BrokenCase;
            transferOrderLoadPlanningAidLinesTmp.Weight = orderExtractScreenTmp.Weight;
            transferOrderLoadPlanningAidLinesTmp.Cube = orderExtractScreenTmp.Volume;

            if (metInventLocation.WHSPalletVolume > 0)
            {
                transferOrderLoadPlanningAidLinesTmp.Pallets = transferOrderLoadPlanningAidLinesTmp.Cube / metInventLocation.WHSPalletVolume;
            }
            else
            {
                transferOrderLoadPlanningAidLinesTmp.Pallets = transferOrderLoadPlanningAidLinesTmp.Cube;
            }

            transferOrderLoadPlanningAidLinesTmp.OrderCreatedDateTime = inventTransferTable.CreatedDateTime;
            transferOrderLoadPlanningAidLinesTmp.OrderSplitCategoryCode = metInventTransferTableExt.OrderSplitGroup;

            transferOrderLoadPlanningAidLinesTmp.ToWarehouseNumber = metInventTransferTableExt.InternalCustomer;
            transferOrderLoadPlanningAidLinesTmp.ToWareHouseName = DirPartyTable::getName(CustTable::find(metInventTransferTableExt.InternalCustomer).Party);
            transferOrderLoadPlanningAidLinesTmp.insert();

            mapIterator.next();
        }
    }
    else
    {
        while select TransferId, Cases, BrokenCase, Weight, Volume from orderExtractScreenTmp
            join ShipDate, TransferId, CreatedDateTime from inventTransferTable
                where inventTransferTable.TransferId == orderExtractScreenTmp.TransferId
            join Route, RouteStopNum, OrderSplitGroup, InternalCustomer from metInventTransferTableExt
                where metInventTransferTableExt.InventTransferTable == inventTransferTable.RecId
                join Name, METWHSubEntity, RecId from inventLocation
                where inventLocation.InventLocationId == inventTransferTable.InventLocationIdFrom
            join WHSPalletVolume from metInventLocation
                where metInventLocation.InventLocation == inventLocation.RecId
            join CompanyName from industryKeyTable
                where industryKeyTable.IndustryKey == inventLocation.METWHSubEntity
        {
            transferOrderLoadPlanningAidLinesTmp.CompanyName = industryKeyTable.CompanyName;
            transferOrderLoadPlanningAidLinesTmp.FromWareHouseName = inventLocation.Name;
            transferOrderLoadPlanningAidLinesTmp.ReportGeneratedDateTime = DateTimeUtil::utcNow();
            transferOrderLoadPlanningAidLinesTmp.Route = metInventTransferTableExt.Route;
            transferOrderLoadPlanningAidLinesTmp.DeliveryDate = inventTransferTable.ShipDate;

            transferOrderLoadPlanningAidLinesTmp.TransferId = inventTransferTable.TransferId;
            transferOrderLoadPlanningAidLinesTmp.RouteStop = metInventTransferTableExt.RouteStopNum;
            transferOrderLoadPlanningAidLinesTmp.Cases = orderExtractScreenTmp.Cases;
            transferOrderLoadPlanningAidLinesTmp.Eaches = orderExtractScreenTmp.BrokenCase;
            transferOrderLoadPlanningAidLinesTmp.Weight = orderExtractScreenTmp.Weight;
            transferOrderLoadPlanningAidLinesTmp.Cube = orderExtractScreenTmp.Volume;

            if (metInventLocation.WHSPalletVolume > 0)
            {
                transferOrderLoadPlanningAidLinesTmp.Pallets = transferOrderLoadPlanningAidLinesTmp.Cube / metInventLocation.WHSPalletVolume;
            }
            else
            {
                transferOrderLoadPlanningAidLinesTmp.Pallets = transferOrderLoadPlanningAidLinesTmp.Cube;
            }

            transferOrderLoadPlanningAidLinesTmp.OrderCreatedDateTime = inventTransferTable.CreatedDateTime;
            transferOrderLoadPlanningAidLinesTmp.OrderSplitCategoryCode = metInventTransferTableExt.OrderSplitGroup;

            transferOrderLoadPlanningAidLinesTmp.ToWarehouseNumber = metInventTransferTableExt.InternalCustomer;
            transferOrderLoadPlanningAidLinesTmp.ToWareHouseName = DirPartyTable::getName(CustTable::find(metInventTransferTableExt.InternalCustomer).Party);
            transferOrderLoadPlanningAidLinesTmp.insert();
        }
    }

    ttscommit;

    return transferOrderLoadPlanningAidLinesTmp.CreatedTransactionId;
}
